?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set admin password</title><link rel="stylesheet" href="css/style.css"><style>body{min-height:100vh;display:grid;place-items:center}.box{width:min(92%,440px);padding:2rem;border:1px solid var(--line-strong);background:var(--surface)}input{display:block;width:100%;margin:1rem 0;padding:.8rem;background:var(--bg);border:1px solid var(--line-strong);color:var(--ink)}code{display:block;word-break:break-all;padding:1rem;background:var(--bg);color:var(--accent)}</style></head><body><main class="box"><p class="mono-label">ONE-TIME SETUP</p><h1>Set password admin</h1><?php if ($hash): ?><p>Password hash untuk admin.php:</p><code><?= htmlspecialchars($hash, ENT_QUOTES, 'UTF-8') ?></code><p>Ganti nilai <code>ADMIN_PASSWORD_HASH</code> di admin.php dengan hash ini, lalu hapus setup-admin.php.</p><?php else: ?><form method="post"><label>Password baru</label><input type="password" name="password" minlength="10" required><button class="button primary" type="submit">Generate hash</button></form><?php endif; ?></main></body></html>
